-- Source: NCA CSCC Assessment and Compliance Tool v2.0 (CSCC-1:2019).
-- Import all 32 primary and 73 sub-controls as an unassigned reference catalog.
insert into public.frameworks(code,name_ar,name_en,version,description_ar,is_active)
values ('CSCC','ضوابط الأمن السيبراني للأنظمة الحساسة','Critical Systems Cybersecurity Controls','1-2019','ضوابط الأمن السيبراني للأنظمة الحساسة الصادرة عن الهيئة الوطنية للأمن السيبراني.',true)
on conflict (code) do update set name_ar=excluded.name_ar,name_en=excluded.name_en,version=excluded.version,description_ar=excluded.description_ar,is_active=true;

create unique index if not exists controls_framework_code_uidx on public.controls(framework_id,control_code);

select setval(
  pg_get_serial_sequence('public.controls','id'),
  coalesce((select max(id) from public.controls),0) + 1,
  false
);

with source(control_code,title_ar,description_ar,domain_ar,control_type,source_row) as (
  values
    ('1-1-1', 'إستراتيجية الأمن السيبراني - 1-1-1', 'بالإضافة للضوابط ضمن المكون الفرعي ١-١ في الضوابط الأساسية للأمن السيبراني، يجب أن تضع إستراتيجية الأمن السيبراني للجهة أولوية لدعم حماية الأنظمة الحساسة الخاصة بالجهة.', 'حوكمة الأمن السيبراني', 'أساسي', 11),
    ('1-2-1', 'إدارة مخاطر الأمن السيبراني - 1-2-1', 'بالإضافة للضوابط ضمن المكون الفرعي ١-٥ في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل منهجية إدارة مخاطر الأمن السيبراني بحد أدنى ما يأتي:', 'حوكمة الأمن السيبراني', 'أساسي', 12),
    ('1-2-1-1', 'إدارة مخاطر الأمن السيبراني - 1-2-1-1', 'تنفيذ إجراء تقييم مخاطر الأمن السيبراني، على الأنظمة الحساسة، مرة واحدة سنوياً، على الأقل.', 'حوكمة الأمن السيبراني', 'فرعي', 13),
    ('1-2-1-2', 'إدارة مخاطر الأمن السيبراني - 1-2-1-2', 'إنشاء سجل مخاطر الأمن السيبراني الخاص بالأنظمة الحساسة، ومتابعته مرة شهرياً على الأقل.', 'حوكمة الأمن السيبراني', 'فرعي', 14),
    ('1-3-1', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-3-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ١-٦-٢ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني، لإدارة المشاريع والتغييرات على الأصول المعلوماتية والتقنية للأنظمة الحساسة في جهة، بحد أدنى؛ ما يلي:', 'حوكمة الأمن السيبراني', 'أساسي', 15),
    ('1-3-1-1', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-3-1-1', 'إجراء اختبار التحمل (Stress Testing) للتأكد من سعة المكونات المختلفة.', 'حوكمة الأمن السيبراني', 'فرعي', 16),
    ('1-3-1-2', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-3-1-2', 'التأكد من تطبيق متطلبات استمرارية الأعمال.', 'حوكمة الأمن السيبراني', 'فرعي', 17),
    ('1-3-2', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-3-2', 'بالإضافة للضوابط الفرعية ضمن الضابط ١-٦-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني، لمشاريع تطوير التطبيقات، والبرمجيات الخاصة بالأنظمة الحساسة للجهة، بحد أدنى؛ ما يلي:', 'حوكمة الأمن السيبراني', 'أساسي', 18),
    ('1-3-2-1', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-3-2-1', 'إجراء مراجعة أمنية للشفرة المصدرية، قبل إطلاقها (Security Source Code Review).', 'حوكمة الأمن السيبراني', 'فرعي', 19),
    ('1-3-2-2', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-3-2-2', 'تأمين الوصول، والتخزين، والتوثيق للشفرة المصدرية (Source Code) وإصداراتها.', 'حوكمة الأمن السيبراني', 'فرعي', 20),
    ('1-3-2-3', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-3-2-3', 'تأمين واجهة برمجة التطبيقات (Authenticated API).', 'حوكمة الأمن السيبراني', 'فرعي', 21),
    ('1-3-2-4', 'الأمن السيبراني ضمن إدارة المشاريع المعلوماتية والتقنية - 1-3-2-4', 'النقل الآمن والموثوق للتطبيقات من بيئات الاختبار (Testing Environment) إلى بيئات الإنتاج (Production Environment ) مع حذف أي بيانات، أو هويات، أو كلمات مرور، متعلقة ببيئات الاختبار، قبل النقل.', 'حوكمة الأمن السيبراني', 'فرعي', 22),
    ('1-4-1', 'المراجعة والتدقيق الدوري للأمن السيبراني - 1-4-1', 'رجوعاً للضابط ١-٨-١ في الضوابط الأساسية للأمن السيبراني، فإنه يجب على الإدارة المعنية بالأمن السيبراني؛ مراجعة تطبيق ضوابط الأمن السيبراني للأنظمة الحساسة، مرة واحدة سنوياً؛ على الأقل.', 'حوكمة الأمن السيبراني', 'أساسي', 23),
    ('1-4-2', 'المراجعة والتدقيق الدوري للأمن السيبراني - 1-4-2', 'رجوعاً للضابط ١-٨-٢ في الضوابط الأساسية للأمن السيبراني، يجب أن تتم مراجعة تطبيق ضوابط الأمن السيبراني للأنظمة الحساسة؛ من قبل أطراف مستقلة عن الإدارة المعنية بالأمن السيبراني من داخل الجهة، مرة واحدة؛ كل ثلاث سنوات على الأقل.', 'حوكمة الأمن السيبراني', 'أساسي', 24),
    ('1-5-1', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-5-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ١-٩-٣ في الضوابط الأساسية للأمن السيبراني، فإنه يجب أن تغطي متطلبات الأمن السيبراني، قبل بدء علاقة العاملين المهنية بالجهة، بحد أدنى؛ ما يلي:', 'حوكمة الأمن السيبراني', 'أساسي', 25),
    ('1-5-1-1', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-5-1-1', 'إجراء المسح الأمني (Screening or Vetting) للعاملين على الأنظمة الحساسة.', 'حوكمة الأمن السيبراني', 'فرعي', 26),
    ('1-5-1-2', 'الأمن السيبراني المتعلق بالموارد البشرية - 1-5-1-2', 'أن يشغل وظائف الدعم، والتطوير التقني، للأنظمة الحساسة؛ مواطنون ذوو كفاءة عالية.', 'حوكمة الأمن السيبراني', 'فرعي', 27),
    ('2-1-1', 'إدارة الأصول - 2-1-1', 'بالإضافة للضوابط ضمن المكون الفرعي ٢-١ في الضوابط الأساسية للأمن السيبراني، يجب أن تشمل متطلبات الأمن السيبراني لإدارة الأصول المعلوماتية والتقنية، بحد أدنى؛ مايلي:', 'تعزيز الأمن السيبراني', 'أساسي', 28),
    ('2-1-1-1', 'إدارة الأصول - 2-1-1-1', 'الاحتفاظ بقائمة محدثة سنوياً، لجميع الأصول التابعة للأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'فرعي', 29),
    ('2-1-1-2', 'إدارة الأصول - 2-1-1-2', 'تحديد ملاك الأصول (Assets Owner) وإشراكهم في دورة حياة إدارة الأصول، التابعة للأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'فرعي', 30),
    ('2-2-1', 'إدارة هويات الدخول والصلاحيات - 2-2-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٢-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني المتعلقة بإدارة هويات الدخول، والصلاحيات للأنظمة الحساسة في الجهة، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني', 'أساسي', 31),
    ('2-2-1-1', 'إدارة هويات الدخول والصلاحيات - 2-2-1-1', 'منع الدخول عن بعد من خارج المملكة.', 'تعزيز الأمن السيبراني', 'فرعي', 32),
    ('2-2-1-2', 'إدارة هويات الدخول والصلاحيات - 2-2-1-2', 'تقييد الدخول عن بعد من داخل المملكة؛ على أن يتم التأكد عن طريق مركز العمليات الأمنية الخاص بالجهة، عند كل عملية دخول؛ ومراقبة الأنشطة المتعلقة بالدخول عن بعد باستمرار.', 'تعزيز الأمن السيبراني', 'فرعي', 33),
    ('2-2-1-3', 'إدارة هويات الدخول والصلاحيات - 2-2-1-3', 'التحقق من الهوية متعدد العناصر (Multi-Factor Authentication "MFA") لجميع المستفيدين.', 'تعزيز الأمن السيبراني', 'فرعي', 34),
    ('2-2-1-4', 'إدارة هويات الدخول والصلاحيات - 2-2-1-4', 'التحقق من الهوية متعدد العناصر (Multi-Factor Authentication "MFA") للمستخدمين ذوي الصلاحيات الهامة، والحساسة؛ وعلى الأنظمة المستخدمة لإدارة الأنظمة الحساسة المذكورة في الضابط ٢-٣-١-٤ ومتابعتها.', 'تعزيز الأمن السيبراني', 'فرعي', 35),
    ('2-2-1-5', 'إدارة هويات الدخول والصلاحيات - 2-2-1-5', 'وضع سياسة آمنة لكلمة المرور ذات معايير عالية، وتطبيقها.', 'تعزيز الأمن السيبراني', 'فرعي', 36),
    ('2-2-1-6', 'إدارة هويات الدخول والصلاحيات - 2-2-1-6', 'استخدام الطرق والخوارزميات الآمنة لحفظ ومعالجة كلمات المرور مثل: استخدام دوال الاختزال (Hashing Functions).', 'تعزيز الأمن السيبراني', 'فرعي', 37),
    ('2-2-1-7', 'إدارة هويات الدخول والصلاحيات - 2-2-1-7', 'الإدارة الآمنة لحسابات الخدمات ((Service Account مابين التطبيقات والأنظمة؛ وتعطيل الدخول البشري التفاعلي (Interactive login) من خلالها.', 'تعزيز الأمن السيبراني', 'فرعي', 38),
    ('2-2-1-8', 'إدارة هويات الدخول والصلاحيات - 2-2-1-8', 'فيما عدا مشرفي قواعد البيانات (Database Administrators)، يمنع الوصول أو التعامل المباشر لأي مستخدم مع قواعد البيانات؛ ويتم ذلك من خلال التطبيقات فقط، وبناءً على الصلاحيات المخوّل بها؛ مع مراعاة تطبيق حلول أمنية تحد، أو تمنع من اطلاع مشرفي قواعد البيانات على البيانات المصنفة (Classified Data).', 'تعزيز الأمن السيبراني', 'فرعي', 39),
    ('2-2-2', 'إدارة هويات الدخول والصلاحيات - 2-2-2', 'رجوعاً للضابط ٢-٢-٣-٥ في الضوابط الأساسية للأمن السيبراني، يجب مراجعة هويات الدخول على الأنظمة الحساسة، مرة واحدة، كل ثلاثة أشهر، على الأقل.', 'تعزيز الأمن السيبراني', 'أساسي', 40),
    ('2-3-1', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٣-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لحماية الأنظمة الحساسة، وأجهزة معالجة المعلومات الخاصة بها، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني', 'أساسي', 41),
    ('2-3-1-1', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-1', 'السماح فقط بقائمة محددة من ملفات التشغيل (Whitelisting) للتطبيقات والبرامج؛ للعمل على الخوادم الخاصة بالأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'فرعي', 42),
    ('2-3-1-2', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-2', 'حماية الخوادم الخاصة بالأنظمة الحساسة بتقنيات حماية الأجهزة الطرفية(End-point Protection) المعتمدة لدى الجهة.', 'تعزيز الأمن السيبراني', 'فرعي', 43),
    ('2-3-1-3', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-3', 'تطبيق حزم التحديثات، والإصلاحات الأمنية، مرة واحدة شهرياً على الأقل، للأنظمة الحساسة الخارجية، والمتصلة بالإنترنت؛ وكل ثلاثة أشهر على الأقل، للأنظمة الحساسة الداخلية؛ مع اتباع آليات التغيير المعتمدة لدى الجهة.', 'تعزيز الأمن السيبراني', 'فرعي', 44),
    ('2-3-1-4', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-4', 'تخصيص أجهزة حاسب (Workstations) للعاملين في الوظائف التقنية، ذات الصلاحيات الهامة والحساسة؛ على أن تكون معزولة في شبكة خاصة، لإدارة الأنظمة (Management Network) وعلى أن لا ترتبط بأي شبكة، أو خدمة أخرى (مثل: خدمة البريد الإلكتروني، الإنترنت).', 'تعزيز الأمن السيبراني', 'فرعي', 45),
    ('2-3-1-5', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-5', 'تشفير أي وصول إشرافي عبر الشبكة (Non-console Administrative Access) لأي من المكونات التقنية للأنظمة الحساسة، باستخدام خوارزميات، وبروتوكولات التشفير الآمنة.', 'تعزيز الأمن السيبراني', 'فرعي', 46),
    ('2-3-1-6', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-6', 'مراجعة إعدادات الأنظمة الحساسة وتحصيناتها (Secure Configuration and Hardening) كل ستة أشهر على الأقل.', 'تعزيز الأمن السيبراني', 'فرعي', 47),
    ('2-3-1-7', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-7', 'مراجعة الإعدادات المصنعية (Default Configuration) وتعديلها والتأكد من عدم وجود كلمات مرور ثابتة، وخلفية، وإفتراضية (Hard-Coded, Backdoor and Default Passwords) ما أمكن تطبيقه.', 'تعزيز الأمن السيبراني', 'فرعي', 48),
    ('2-3-1-8', 'حماية الأنظمة وأجهزة معالجة المعلومات - 2-3-1-8', 'حماية السجلات، والملفات الحساسة للأنظمة، من الوصول غير المصرح به، أو العبث، أو التغيير، أو الحذف غير المشروع.', 'تعزيز الأمن السيبراني', 'فرعي', 49),
    ('2-4-1', 'إدارة أمن الشبكات - 2-4-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٥-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة أمن شبكات الأنظمة الحساسة للجهة بحد أدنى ما يلي:', 'تعزيز الأمن السيبراني', 'أساسي', 50),
    ('2-4-1-1', 'إدارة أمن الشبكات - 2-4-1-1', 'العزل والتقسيم المادي، أو المنطقي، لشبكات الأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'فرعي', 51),
    ('2-4-1-2', 'إدارة أمن الشبكات - 2-4-1-2', 'مراجعة إعدادات جدار الحماية (Firewall rules) وقوائمه؛ كل ستة أشهر، على الأقل.', 'تعزيز الأمن السيبراني', 'فرعي', 52),
    ('2-4-1-3', 'إدارة أمن الشبكات - 2-4-1-3', 'منع التوصيل المباشر، لأي جهاز بالشبكة المحلية للأنظمة الحساسة؛ إلا بعد الفحص، والتأكد من توافر عناصر الحماية المحققة، للمستويات المقبولة للأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'فرعي', 53),
    ('2-4-1-4', 'إدارة أمن الشبكات - 2-4-1-4', 'منع الأنظمة الحساسة من الاتصال بالشبكة اللاسلكية.', 'تعزيز الأمن السيبراني', 'فرعي', 54),
    ('2-4-1-5', 'إدارة أمن الشبكات - 2-4-1-5', 'الحماية من التهديدات المتقدمة المستمرة على مستوى الشبكة (Network APT).', 'تعزيز الأمن السيبراني', 'فرعي', 55),
    ('2-4-1-6', 'إدارة أمن الشبكات - 2-4-1-6', 'منع الأنظمة الحساسة من الاتصال بالإنترنت في حال أن كانت تقدم خدمة داخلية للجهة؛ ولا توجد هناك حاجة ضرورية جداً، للدخول على الخدمة من خارج الجهة.', 'تعزيز الأمن السيبراني', 'فرعي', 56),
    ('2-4-1-7', 'إدارة أمن الشبكات - 2-4-1-7', 'تقديم خدمات الأنظمة الحساسة، من خلال شبكات مستقلة عن الإنترنت، في حال أن كانت خدمات تلك الأنظمة، موجهة لجهات محدودة؛ وليست للأفراد.', 'تعزيز الأمن السيبراني', 'فرعي', 57),
    ('2-4-1-8', 'إدارة أمن الشبكات - 2-4-1-8', 'الحماية من هجمات تعطيل الشبكات ("Distrbuted Denial of Service Attack "DDoS) للحد من المخاطر الناتجة عن هجمات تعطيل الشبكات.', 'تعزيز الأمن السيبراني', 'فرعي', 58),
    ('2-4-1-9', 'إدارة أمن الشبكات - 2-4-1-9', 'السماح بقائمة محددة (Whitelisting) فقط، لقوائم جدار الحماية، الخاصة بالأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'فرعي', 59),
    ('2-5-1', 'أمن الأجهزة المحمولة - 2-5-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٦-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني، الخاصة بأمن الأجهزة المحمولة، وأجهزة (BYOD) للجهة، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني', 'أساسي', 60),
    ('2-5-1-1', 'أمن الأجهزة المحمولة - 2-5-1-1', 'منع الوصول من الأجهزة المحمولة للأنظمة الحساسة، إلا لفترة مؤقتة فقط؛ وذلك بعد إجراء تقييم المخاطر، وأخذ الموافقات اللازمة من الإدارة المعنية بالأمن السيبراني في الجهة.', 'تعزيز الأمن السيبراني', 'فرعي', 61),
    ('2-5-1-2', 'أمن الأجهزة المحمولة - 2-5-1-2', 'تشفير أقراص الأجهزة المحمولة، ذات صلاحية الوصول للأنظمة الحساسة، تشفيراً كاملاً (Full Disk Encryption).', 'تعزيز الأمن السيبراني', 'فرعي', 62),
    ('2-6-1', 'حماية البيانات والمعلومات - 2-6-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٧-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لحماية البيانات والمعلومات؛ بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'أساسي', 63),
    ('2-6-1-1', 'حماية البيانات والمعلومات - 2-6-1-1', 'عدم استخدام بيانات الأنظمة الحساسة في غير بيئة الإنتاج (Production Environment) إلا بعد استخدام ضوابط مشددة لحماية تلك البيانات مثل: تقنيات تعتيم البيانات (Data Masking) أو تقنيات مزج البيانات (Data Scrambling).', 'تعزيز الأمن السيبراني', 'فرعي', 64),
    ('2-6-1-2', 'حماية البيانات والمعلومات - 2-6-1-2', 'تصنيف جميع بيانات الأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'فرعي', 65),
    ('2-6-1-3', 'حماية البيانات والمعلومات - 2-6-1-3', 'حماية البيانات المصنفة الخاصة بالأنظمة الحساسة من خلال تقنيات، منع تسريب البيانات (Data Leakage Prevention).', 'تعزيز الأمن السيبراني', 'فرعي', 66),
    ('2-6-1-4', 'حماية البيانات والمعلومات - 2-6-1-4', 'تحديد مدة الاحتفاظ المطلوبة (Retention Period) لبيانات الأعمال المتعلقة بالأنظمة الحساسة؛ حسب التشريعات ذات العلاقة، ويتم الاحتفاظ بالبيانات المطلوبة فقط، في بيئات الإنتاج للأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'فرعي', 67),
    ('2-6-1-5', 'حماية البيانات والمعلومات - 2-6-1-5', 'منع نقل أي من بيانات بيئة الإنتاج الخاصة بالأنظمة الحساسة إلى أي بيئة أخرى.', 'تعزيز الأمن السيبراني', 'فرعي', 68),
    ('2-7-1', 'التشفير - 2-7-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٨-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني للتشفير، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'أساسي', 69),
    ('2-7-1-1', 'التشفير - 2-7-1-1', 'تشفير جميع بيانات الأنظمة الحساسة؛ أثناء النقل (Data-In-Transit).', 'تعزيز الأمن السيبراني', 'فرعي', 70),
    ('2-7-1-2', 'التشفير - 2-7-1-2', 'تشفير جميع بيانات الأنظمة الحساسة؛ أثناء التخزين (Data-At-Rest) على مستوى الملفات، أو قاعدة البيانات، أو على مستوى أعمدة محددة، داخل قاعدة البيانات.', 'تعزيز الأمن السيبراني', 'فرعي', 71),
    ('2-7-1-3', 'التشفير - 2-7-1-3', 'استخدام طرق وخوارزميات ومفاتيح وأجهزة تشفير محدثة وآمنة وفقاً لما تصدره الهيئة بهذا الشأن.', 'تعزيز الأمن السيبراني', 'فرعي', 72),
    ('2-8-1', 'إدارة النسخ الاحتياطية - 2-8-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-٩-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة النسخ الاحتياطية، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني', 'أساسي', 73),
    ('2-8-1-1', 'إدارة النسخ الاحتياطية - 2-8-1-1', 'نطاق عمل النسخ الاحتياطي المتصل، وغير المتصل (Online and Offline backup) ليشمل جميع الأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'فرعي', 74),
    ('2-8-1-2', 'إدارة النسخ الاحتياطية - 2-8-1-2', 'عمل النسخ الاحتياطي على فترات زمنية مخطط لها؛ بناءً على تقييم المخاطر للجهة. وتوصي الهيئة بأن يتم عمل النسخ الاحتياطي، للأنظمة الحساسة، بشكل يومي.', 'تعزيز الأمن السيبراني', 'فرعي', 75),
    ('2-8-1-3', 'إدارة النسخ الاحتياطية - 2-8-1-3', 'تأمين الوصول، والتخزين، والنقل لمحتوى النسخ الاحتياطية للأنظمة الحساسة ووسائطها، وحمايتها من الإتلاف، أو التعديل، أو الاطلاع غير المصرح به.', 'تعزيز الأمن السيبراني', 'فرعي', 76),
    ('2-8-2', 'إدارة النسخ الاحتياطية - 2-8-2', 'رجوعاً للضابط ٢-٩-٣-٣ في الضوابط الأساسية للأمن السيبراني، يجب إجراء فحص دوري؛ كل ثلاثة أشهر على الأقل، لتحديد مدى فعالية استعادة النسخ الاحتياطية، الخاصة بالأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'أساسي', 77),
    ('2-9-1', 'إدارة الثغرات - 2-9-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-١٠-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لإدارة الثغرات للأنظمة الحساسة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'أساسي', 78),
    ('2-9-1-1', 'إدارة الثغرات - 2-9-1-1', 'استخدام وسائل وأدوات موثوقة لإكتشاف الثغرات.', 'تعزيز الأمن السيبراني', 'فرعي', 79),
    ('2-9-1-2', 'إدارة الثغرات - 2-9-1-2', 'تقييم الثغرات ومعالجتها (بتنصيب حزم التحديثات والإصلاحات) على المكونات التقنية للأنظمة الحساسة، مرة واحدة شهرياً، على الأقل، للأنظمة الحساسة الخارجية، والمتصلة بالإنترنت؛ وكل ثلاثة أشهر على الأقل، للأنظمة الحساسة الداخلية.', 'تعزيز الأمن السيبراني', 'فرعي', 80),
    ('2-9-1-3', 'إدارة الثغرات - 2-9-1-3', 'معالجة فورية للثغرات الحرجة (Critical Vulnerabilities) المكتشفة حديثاً؛ مع اتباع آليات إدارة التغيير، المعتمدة لدى الجهة.', 'تعزيز الأمن السيبراني', 'فرعي', 81),
    ('2-9-2', 'إدارة الثغرات - 2-9-2', 'رجوعاً للضابط ٢-١٠-٣-١ في الضوابط الأساسية للأمن السيبراني، يجب فحص الثغرات واكتشافها على المكونات التقنية، للأنظمة الحساسة، مرة واحدة شهرياً؛ على الأقل.', 'تعزيز الأمن السيبراني', 'أساسي', 82),
    ('2-10-1', 'اختبار الاختراق - 2-10-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-١١-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني لاختبار الاختراق للأنظمة الحساسة، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني', 'أساسي', 83),
    ('2-10-1-1', 'اختبار الاختراق - 2-10-1-1', 'نطاق عمل اختبار الاختراق، ليشمل جميع المكونات التقنية للأنظمة الحساسة، وجميع الخدمات المقدمة داخلياً وخارجياً.', 'تعزيز الأمن السيبراني', 'فرعي', 84),
    ('2-10-1-2', 'اختبار الاختراق - 2-10-1-2', 'عمل اختبار الاختراق من قبل فريق مؤهل.', 'تعزيز الأمن السيبراني', 'فرعي', 85),
    ('2-10-2', 'اختبار الاختراق - 2-10-2', 'رجوعاً للضابط ٢-١١-٣-٢ في الضوابط الأساسية للأمن السيبراني، يجب عمل اختبار الاختراق على الأنظمة الحساسة، كل ستة أشهر؛ على الأقل.', 'تعزيز الأمن السيبراني', 'أساسي', 86),
    ('2-11-1', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-١٢-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات إدارة سجلات الأحداث، ومراقبة الأمن السيبراني للأنظمة الحساسة، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني', 'أساسي', 87),
    ('2-11-1-1', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1-1', 'تفعيل سجلات الأحداث (Event logs) الخاصة بالأمن السيبراني؛ على جميع المكونات التقنية للأنظمة الحساسة.', 'تعزيز الأمن السيبراني', 'فرعي', 88),
    ('2-11-1-2', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1-2', 'تفعيل التنبيهات وسجلات الأحداث المتعلقة بإدارة تغييرات الملفات (File Integrity Management) ومراقبتها.', 'تعزيز الأمن السيبراني', 'فرعي', 89),
    ('2-11-1-3', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1-3', 'مراقبة سلوك المستخدم ("User Behavior Analytics "UBA) وتحليله.', 'تعزيز الأمن السيبراني', 'فرعي', 90),
    ('2-11-1-4', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1-4', 'مراقبة سجلات الأحداث، الخاصة بالأنظمة الحساسة على مدار الساعة.', 'تعزيز الأمن السيبراني', 'فرعي', 91),
    ('2-11-1-5', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-1-5', 'الاحتفاظ بسجلات الأحداث، الخاصة بالأمن السيبراني، المتعلقة بالأنظمة الحساسة وحمايتها؛ على أن تكون شاملة، ومتضمنة للتفاصيل كاملة (مثل: الوقت، التاريخ، الهوية، النظام المتأثر).', 'تعزيز الأمن السيبراني', 'فرعي', 92),
    ('2-11-2', 'إدارة سجلات الأحداث ومراقبة الأمن السيبراني - 2-11-2', 'رجوعاً للضابط ٢-١٢-٣-٥ في الضوابط الأساسية للأمن السيبراني، يجب أن لا تقل مدة الاحتفاظ بسجلات الأحداث الخاصة بالأمن السيبراني، على الأنظمة الحساسة عن ١٨ شهراً؛ حسب المتطلبات التشريعية، والتنظيمية، ذات العلاقة.', 'تعزيز الأمن السيبراني', 'أساسي', 93),
    ('2-12-1', 'حماية تطبيقات الويب - 2-12-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٢-١٥-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني، لحماية تطبيقات الويب الخارجية للأنظمة الحساسة للجهة، بحد أدنى؛ ما يلي:', 'تعزيز الأمن السيبراني', 'أساسي', 94),
    ('2-12-1-1', 'حماية تطبيقات الويب - 2-12-1-1', 'الإدارة الآمنة للجلسات (Secure Session Management)، ويشمل موثوقية الجلسات (Authenticity)، وإقفالها (Lockout)، وإنهاء مهلتها (Timeout ).', 'تعزيز الأمن السيبراني', 'فرعي', 95),
    ('2-12-1-2', 'حماية تطبيقات الويب - 2-12-1-2', 'تطبيق معايير أمن التطبيقات وحمايتها (OWASP Top Ten) في حدها الأدنى.', 'تعزيز الأمن السيبراني', 'فرعي', 96),
    ('2-12-2', 'حماية تطبيقات الويب - 2-12-2', 'رجوعاً للضابط ٢-١٥-٣-٢ في الضوابط الأساسية للأمن السيبراني، يجب استخدام مبدأ المعمارية ذات المستويات المتعددة (Multi-tier Architecture) على أن لا يقل عدد المستويات عن ٣ (3-Tier Architecture).', 'تعزيز الأمن السيبراني', 'أساسي', 97),
    ('2-13-1', 'حماية التطبيقات - 2-13-1', 'يجب تحديد وتوثيق واعتماد متطلبات الأمن السيبراني لحماية التطبيقات الداخلية الخاصة بالأنظمة الحساسة للجهة من المخاطر السيبرانية.', 'تعزيز الأمن السيبراني', 'أساسي', 98),
    ('2-13-2', 'حماية التطبيقات - 2-13-2', 'يجب تطبيق متطلبات الأمن السيبراني؛ لحماية التطبيقات الداخلية، الخاصة بالأنظمة الحساسة للجهة.', 'تعزيز الأمن السيبراني', 'أساسي', 99),
    ('2-13-3', 'حماية التطبيقات - 2-13-3', 'يجب أن تغطي متطلبات الأمن السيبراني؛ لحماية التطبيقات الداخلية، الخاصة بالأنظمة الحساسة للجهة، بحد أدنى، ما يلي:', 'تعزيز الأمن السيبراني', 'أساسي', 100),
    ('2-13-3-1', 'حماية التطبيقات - 2-13-3-1', 'استخدام مبدأ المعمارية ذات المستويات المتعددة (Multi-tier Architecture) على أن لا يقل عدد المستويات عن ٣ (3-Tier Architecture).', 'تعزيز الأمن السيبراني', 'فرعي', 101),
    ('2-13-3-2', 'حماية التطبيقات - 2-13-3-2', 'استخدام بروتوكولات آمنة (مثل بروتوكول HTTPS).', 'تعزيز الأمن السيبراني', 'فرعي', 102),
    ('2-13-3-3', 'حماية التطبيقات - 2-13-3-3', 'توضيح سياسة الاستخدام الآمن للمستخدمين.', 'تعزيز الأمن السيبراني', 'فرعي', 103),
    ('2-13-3-4', 'حماية التطبيقات - 2-13-3-4', 'الإدارة الآمنة للجلسات (Secure Session Management)، ويشمل موثوقية الجلسات (Authenticity)، وإقفالها (Lockout)، وإنهاء مهلتها (Timeout).', 'تعزيز الأمن السيبراني', 'فرعي', 104),
    ('2-13-4', 'حماية التطبيقات - 2-13-4', 'مراجعة متطلبات الأمن السيبراني لحماية التطبيقات الداخلية الخاصة بالأنظمة الحساسة للجهة دورياً.', 'تعزيز الأمن السيبراني', 'أساسي', 105),
    ('3-1-1', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال - 3-1-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٣-١-٣ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي إدارة استمرارية الأعمال في الجهة، بحد أدنى؛ ما يلي:', 'صمود الأمن السيبراني', 'أساسي', 106),
    ('3-1-1-1', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال - 3-1-1-1', 'وضع مركز للتعافي من الكوارث للأنظمة الحساسة.', 'صمود الأمن السيبراني', 'فرعي', 107),
    ('3-1-1-2', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال - 3-1-1-2', 'إدراج الأنظمة الحساسة؛ ضمن خطط التعافي من الكوارث.', 'صمود الأمن السيبراني', 'فرعي', 108),
    ('3-1-1-3', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال - 3-1-1-3', 'إجراء اختبارات دورية؛ للتأكد من فعالية خطط التعافي، من الكوارث للأنظمة الحساسة، مرة واحدة سنوياً؛ على الأقل.', 'صمود الأمن السيبراني', 'فرعي', 109),
    ('3-1-1-4', 'جوانب صمود الأمن السيبراني في إدارة استمرارية الأعمال - 3-1-1-4', 'توصي الهيئة بإجراء اختبار دوري حي؛ للتعافي من الكوارث (Live DR Test) للأنظمة الحساسة.', 'صمود الأمن السيبراني', 'فرعي', 110),
    ('4-1-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 4-1-1', 'بالإضافة للضوابط ضمن المكون الفرعي ٤-١ في الضوابط الأساسية للأمن السيبراني، يجب أن تغطي متطلبات الأمن السيبراني، المتعلقة بالأطراف الخارجية، بحد أدنى؛ ما يلي:', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'أساسي', 111),
    ('4-1-1-1', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 4-1-1-1', 'إجراء المسح الأمني (Screening or Vetting) لشركات خدمات الإسناد، ولموظفي خدمات الإسناد، والخدمات المدارة العاملين على الأنظمة الحساسة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', 112),
    ('4-1-1-2', 'الأمن السيبراني المتعلق بالأطراف الخارجية - 4-1-1-2', 'أن تكون خدمات الإسناد، والخدمات المدارة على الأنظمة الحساسة؛ عن طريق شركات، وجهات وطنية؛ وفقًا للمتطلبات التشريعية، والتنظيمية ذات العلاقة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', 113),
    ('4-2-1', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة - 4-2-1', 'بالإضافة للضوابط الفرعية ضمن الضابط ٤-٢-٣ في الضوابط الأساسية للأمن السيراني، يجب أن تغطي متطلبات الأمن السيبراني الخاصة باستخدام خدمات الحوسبة السحابية والاستضافة، بحد أدنى؛ ما يلي:', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'أساسي', 114),
    ('4-2-1-1', 'الأمن السيبراني المتعلق بالحوسبة السحابية والاستضافة - 4-2-1-1', 'أن يكون موقع استضافة الأنظمة الحساسة، أو أي جزء من مكوناتها التقنية، داخل الجهة، أو في خدمات الحوسبة السحابية، المقدمة من قبل جهات حكومية، أو شركات وطنية محققة لضوابط الحوسبة السحابية الصادرة من الهيئة مع مراعاة تصنيف البيانات المستضافة.', 'الأمن السيبراني المتعلق بالأطراف الخارجية والحوسبة السحابية', 'فرعي', 115)
), framework as (select id from public.frameworks where code='CSCC')
insert into public.controls(framework_id,control_code,title_ar,description_ar,domain_ar,implementation_status,evidence_status,verification_status)
select framework.id,source.control_code,source.title_ar,source.description_ar,source.domain_ar,'not_started','not_uploaded','not_verified'
from source cross join framework
on conflict (framework_id,control_code) do update set title_ar=excluded.title_ar,description_ar=excluded.description_ar,domain_ar=excluded.domain_ar;

create or replace function public.cgp_dashboard()
returns jsonb language sql stable set search_path to '' as $$
with scoped as (
  select c.* from public.controls c join public.frameworks f on f.id=c.framework_id
  where f.code='ECC' and (
    (select private.current_user_role()) in ('admin','cybersecurity_team') or
    ((select private.current_user_role())='control_owner' and c.control_owner_id=(select auth.uid()))
  )
), totals as (
  select count(*) total,
  count(*) filter(where lower(trim(implementation_status)) in ('implemented','compliant')) done,
  count(*) filter(where lower(trim(evidence_status)) not in ('uploaded','pending_review','under_review','accepted','approved','verified')) waiting_evidence,
  count(*) filter(where due_date < (now() at time zone 'Asia/Riyadh')::date and lower(trim(implementation_status)) not in ('implemented','compliant')) overdue,
  count(*) filter(where lower(trim(verification_status)) in ('verified','approved')) verified from scoped
), domains as (
  select domain_ar name,count(*) total,count(*) filter(where lower(trim(implementation_status)) in ('implemented','compliant')) done from scoped group by domain_ar
)
select jsonb_build_object('total',t.total,'compliance',case when t.total=0 then 0 else round(100.0*t.done/t.total) end,
'waiting_evidence',t.waiting_evidence,'overdue',t.overdue,'verified',t.verified,
'pending_review',(select count(*) from public.evidence e join scoped c on c.id=e.control_id where e.is_current and e.status in ('pending_review','under_review')),
'domains',coalesce((select jsonb_agg(jsonb_build_object('name',d.name,'total',d.total,'done',d.done,'percentage',round(100.0*d.done/d.total)) order by d.name) from domains d),'[]'::jsonb)) from totals t;
$$;
